66	export function isMentionElement(node: HastElement): boolean {
67	  if (hasExtendedData(node) && node.data.mdastType === "mentionNode") {
68	    return true;
69	  }
70	
71	  const dataMention = node.properties?.["data-mention"];
72	  if (typeof dataMention === "string" && dataMention !== "") {
73	    return true;
74	  }
75	
76	  const className = node.properties?.className;
